import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import { parseFrame, ingestDevice, type Reading } from "../src/telemetry/ingest.ts";
import { BoundedChannel } from "../src/telemetry/channel.ts";
import { runGateway } from "../src/telemetry/gateway.ts";

// A device connection that sends `count` readings as fast as it is read. `pulled` counts frames read so far.
function chattyDevice(deviceId: string, count: number) {
    const device = {
        deviceId,
        pulled: 0,
        frames: (async function* () {
            for (let i = 1; i <= count; i++) {
                device.pulled++;
                yield `temp_c ${20 + (i % 5)} ${1_700_000_000_000 + i}`;
            }
        })(),
    };
    return device;
}

// Storage that takes a couple of event-loop turns per write, like a remote time-series database.
function slowStore(onWrite: (points: Reading[]) => void = () => {}) {
    const points: Reading[] = [];
    return {
        points,
        async writeBatch(batch: Reading[]) {
            onWrite(batch);
            await tick();
            await tick();
            points.push(...batch);
        },
    };
}

test("frames are parsed into readings and malformed frames are rejected", () => {
    assert.deepEqual(parseFrame("d1", " humidity 41.5 1700000000123 "), { deviceId: "d1", metric: "humidity", value: 41.5, at: 1700000000123 });
    assert.equal(parseFrame("d1", "humidity 41.5"), null);
    assert.equal(parseFrame("d1", "Humidity 41.5 1700000000123"), null);
    assert.equal(parseFrame("d1", "humidity NaN 1700000000123"), null);
    assert.equal(parseFrame("d1", "humidity 3 -5"), null);
});

test("every valid reading is written once, in the order each device sent it", async () => {
    const a = chattyDevice("a", 40);
    const b = chattyDevice("b", 25);
    const store = slowStore();
    const report = await runGateway([a, b], store, { capacity: 8, batchSize: 5 });
    assert.equal(report.written, 65);
    assert.equal(store.points.length, 65);
    for (const id of ["a", "b"]) {
        const times = store.points.filter((p) => p.deviceId === id).map((p) => p.at);
        assert.deepEqual(times, [...times].sort((x, y) => x - y));
    }
});

test("rejected frames are counted and never reach storage", async () => {
    const frames = (async function* () {
        yield "temp_c 21 1700000000001";
        yield "garbage";
        yield "temp_c 22 1700000000002";
        yield "temp_c x 1700000000003";
    })();
    const store = slowStore();
    const report = await runGateway([{ deviceId: "d9", frames }], store, { capacity: 4, batchSize: 10 });
    assert.deepEqual([report.accepted, report.rejected, report.written], [2, 2, 2]);
    assert.deepEqual(store.points.map((p) => p.value), [21, 22]);
});

test("a device flooding the gateway is held to the channel's capacity while storage is slow", async () => {
    const device = chattyDevice("floody", 500);
    const report = await runGateway([device], slowStore(), { capacity: 10, batchSize: 5 });
    console.log(`peak readings held in memory: ${report.peakHeld} (capacity 10)`);
    assert.equal(report.written, 500);
    assert.ok(report.peakHeld <= 11, `held ${report.peakHeld} readings at once`);
});

test("a device connection is not read far ahead of what storage has written", async () => {
    const device = chattyDevice("sensor-7", 300);
    let written = 0;
    let worstLead = 0;
    const store = slowStore((batch) => {
        worstLead = Math.max(worstLead, device.pulled - written);
        written += batch.length;
    });
    await runGateway([device], store, { capacity: 10, batchSize: 5 });
    assert.ok(worstLead <= 10 + 5 + 2, `device was read ${worstLead} frames ahead of storage`);
});

test("many devices at once park at most one reading each beyond capacity", async () => {
    const devices = Array.from({ length: 6 }, (_, i) => chattyDevice(`dev-${i}`, 120));
    const report = await runGateway(devices, slowStore(), { capacity: 20, batchSize: 10 });
    assert.equal(report.written, 720);
    assert.ok(report.peakHeld <= 20 + 6, `held ${report.peakHeld} readings at once`);
});

test("ingesting a device only finishes once its last reading is in the channel", async () => {
    const channel = new BoundedChannel<Reading>(3);
    const device = chattyDevice("d1", 5);
    const stats = { accepted: 0, rejected: 0 };
    let done = false;
    const ingest = ingestDevice("d1", device.frames, channel, stats).then(() => (done = true));
    await tick();
    assert.equal(done, false, "two readings can't fit yet");
    const first = await channel.receive();
    assert.equal(first.value?.at, 1_700_000_000_001);
    await channel.receive();
    await ingest;
    assert.equal(stats.accepted, 5);
});
